<?php
// AI generated by pi coding agent, v1.0
declare(strict_types=1);

/**
 * GET api/years.php
 *
 * Lists the calendar years that contain measurements, newest first, plus the
 * calendar year the database considers current. The dashboard uses this to
 * build its "past years" dropdown - the number of years is not hard-coded.
 *
 * `YEAR(measured_at)` uses the naive Pi-local timestamp, which is exactly what
 * the user expects to see in a year selector.
 */

require __DIR__ . '/bootstrap.php';

try {
    $rows = db()
        ->query('SELECT YEAR(measured_at) AS year, COUNT(*) AS row_count
                   FROM measurements
                  GROUP BY YEAR(measured_at)
                  ORDER BY year DESC')
        ->fetchAll();

    $currentYear = (int) db()->query('SELECT YEAR(NOW())')->fetchColumn();
} catch (PDOException $e) {
    error_log('pi_sensor: years query failed: ' . $e->getMessage());
    json_error('Abfrage fehlgeschlagen', 503);
}

$years = [];
foreach ($rows as $row) {
    $years[] = [
        'year' => (int) $row['year'],
        'rows' => (int) $row['row_count'],
    ];
}

json_out([
    'current_year' => $currentYear,
    'years' => $years,
], 200, 3600);
// End of AI generated by pi coding agent, v1.0
